["version"] = 20250728,
["warnings"] = "The import for 'core' required some automated changes.\nThe following auras were used in the action list but were not found in the addon database:\n - desperate_measures\n\nThe import for 'default' required some automated changes.\nLine 4: Converted operations in '(chi.current==5*talent.ascension.enabled+4*!talent.ascension.enabled)' to '(chi.current=5*talent.ascension.enabled+4*!talent.ascension.enabled)'.\n\nThe import for 'overflow' required some automated changes.\nLine 1: Converted operations in 'chi.current==5*talent.ascension.enabled+4*!talent.ascension.enabled&buff.shuffle.remains>8&(debuff.dizzying_haze.up||debuff.dizzying_haze_dot.up)&debuff.breath_of_fire_dot.down&health.percent>=70' to 'chi.current=5*talent.ascension.enabled+4*!talent.ascension.enabled&buff.shuffle.remains>8&(debuff.dizzying_haze.up||debuff.dizzying_haze_dot.up)&debuff.breath_of_fire_dot.down&health.percent>=70'.\nLine 2: Converted operations in 'chi.current==5*talent.ascension.enabled+4*!talent.ascension.enabled&buff.guard.down&buff.shuffle.remains>8&health.percent<=70' to 'chi.current=5*talent.ascension.enabled+4*!talent.ascension.enabled&buff.guard.down&buff.shuffle.remains>8&health.percent<=70'.\nLine 3: Converted operations in 'chi.current==5*talent.ascension.enabled+4*!talent.ascension.enabled' to 'chi.current=5*talent.ascension.enabled+4*!talent.ascension.enabled'.\n\nThe import for 'defensives' required some automated changes.\nLine 4: Converted operations in 'chi.current>=2&buff.guard.down&buff.fortifying_brew.down&(stagger_level==3||health.percent<=70)&buff.tiger_power.up' to 'chi.current>=2&buff.guard.down&buff.fortifying_brew.down&(stagger_level=3||health.percent<=70)&buff.tiger_power.up'.\nThe following auras were used in the action list but were not found in the addon database:\n - elusive_brew_buff\n\nThe import for 'precombat' required some automated changes.\nLine 1: Unsupported action 'stance_of_the_sturdy_ox'.\n\nThis profile is missing support for generic trinkets.  It is recommended that every priority includes either:\n - [Use Items], which includes any trinkets not explicitly included in the priority; or\n - [Trinket 1] and [Trinket 2], which will recommend the trinket for the numbered slot.\nImported 9 action lists.\n",
["profile"] = "# =======================\n# Precombat setup\n# =======================\nactions.precombat=stance_of_the_sturdy_ox\n\n# =======================\n# Defensives\n# =======================\n\n\n# Use Elusive Brew when stacks are high, HP is not full, Guard is down, and you don’t already have the dodge buff\nactions.defensives+=elusive_brew,if=buff.elusive_brew_stacks.stack>=10&health.percent<100&buff.guard.down&buff.elusive_brew_buff.down\n\n\n# Purifying Brew - Heavy stagger (40%+) and Guard is not active\nactions.defensives+=/purifying_brew,if=chi.current>=1&settings.use_purifying_brew&!cooldown.guard.ready&stagger_level>=3\n\n# Purifying Brew - Moderate stagger (30%+) if low HP or Guard is on cooldown and stagger rising\nactions.defensives+=/purifying_brew,if=chi.current>=1&settings.use_purifying_brew&(health.percent<=40||!cooldown.guard.ready)&stagger_level>=2\n\n# Use Guard proactively for high stagger or HP ≤ 70% if Fortifying Brew isn't active with tiger palm buff\nactions.defensives+=/guard,if=chi.current>=2&buff.guard.down&buff.fortifying_brew.down&(stagger_level== 3||health.percent<=70)&buff.tiger_power.up\n\n# Fortifying Brew - Use if Guard is down and either HP is low or stagger is high wants to change level to amount later\nactions.defensives+=/fortifying_brew,if=buff.guard.down&(health.percent<=50||stagger_level>3)\n\n# Dampen Harm - Last line of defense when everything else is down and you're in danger\nactions.defensives+=/dampen_harm,if=buff.dampen_harm.down&buff.fortifying_brew.down&buff.guard.down&health.percent<=40\n\n# =======================\n# Touch Of Death\n# =======================\n\n# Fire ToD immediately if at 3+ Chi and meets boss/trash rules\nactions.tod+=/touch_of_death,if=chi.current>=3&(boss||target.health.pct>=20)\n\n# Dump Chi if capped before building\nactions.tod+=/blackout_kick,if=chi.current>=5*talent.ascension.enabled+4*!talent.ascension.enabled\n\n# Keg Smash (+2 Chi) – no overcap\nactions.tod+=/keg_smash,if=chi.current<=5*talent.ascension.enabled+4*!talent.ascension.enabled-2&chi.current<3&energy.actual>=40\n\n# RJW (+1, or +2 with PS) – no overcap\nactions.tod+=/rushing_jade_wind,if=active_enemies>=3&talent.rushing_jade_wind.enabled&cooldown.rushing_jade_wind.ready&((buff.power_strikes.up&chi.current<=5*talent.ascension.enabled+4*!talent.ascension.enabled-2)||(!buff.power_strikes.up&chi.current<=5*talent.ascension.enabled+4*!talent.ascension.enabled-1))&chi.current<3\n\n# SCK (+1, or +2 with PS) – no overcap\nactions.tod+=/spinning_crane_kick,if=active_enemies>=3&!talent.rushing_jade_wind.enabled&energy.actual>=40&((buff.power_strikes.up&chi.current<=5*talent.ascension.enabled+4*!talent.ascension.enabled-2)||(!buff.power_strikes.up&chi.current<=5*talent.ascension.enabled+4*!talent.ascension.enabled-1))&chi.current<3&buff.shuffle.remains>1.9\n\n# Expel Harm (+2, or +3 with PS) – no overcap\nactions.tod+=/expel_harm,if=health.percent<100&energy.actual>=40&((buff.power_strikes.up&chi.current<=5*talent.ascension.enabled+4*!talent.ascension.enabled-3)||(!buff.power_strikes.up&chi.current<=5*talent.ascension.enabled+4*!talent.ascension.enabled-2))&chi.current<3\n\n# Jab (+1, or +2 with PS) – no overcap\nactions.tod+=/jab,if=energy.actual>=40&((buff.power_strikes.up&chi.current<=5*talent.ascension.enabled+4*!talent.ascension.enabled-2)||(!buff.power_strikes.up&chi.current<=5*talent.ascension.enabled+4*!talent.ascension.enabled-1))&chi.current<3\n\n# Fire ToD again at the end in case we reached 3 Chi from builders\nactions.tod+=/touch_of_death,if=chi.current>=3&(boss||target.health.pct>20)\n\n# =======================\n# Cooldowns\n# =======================\n\n# Use Energizing Brew if low on energy and Chi\nactions.cooldowns+=/energizing_brew,if=energy.actual<=40&chi.current<=1\n\n# Use Chi Brew if talented and Chi is low\nactions.cooldowns+=/chi_brew,if=talent.chi_brew.enabled&chi.current<2&buff.elusive_brew.stack<9\n\n\n# =======================\n# Chi Overflow\n# =======================\n\n# Use Breath of Fire if Dizzying Haze is up, target isn't burning, and Shuffle is banked\nactions.overflow+=/breath_of_fire,if=chi.current==5*talent.ascension.enabled+4*!talent.ascension.enabled&buff.shuffle.remains>8&(debuff.dizzying_haze.up||debuff.dizzying_haze_dot.up)&debuff.breath_of_fire_dot.down&health.percent>=70\n\n# Use Guard when at Chi cap and it's off CD, even if not in danger\nactions.overflow+=/guard,if=chi.current==5*talent.ascension.enabled+4*!talent.ascension.enabled&buff.guard.down&buff.shuffle.remains>8&health.percent<=70\n\n# Chi dump if capped and Guard not used\nactions.overflow+=/blackout_kick,if=chi.current==5*talent.ascension.enabled+4*!talent.ascension.enabled\n\n\n# =======================\n# Core (Shared Logic)\n# =======================\n\n\n# Maintain Shuffle buff if missing\nactions.core+=/blackout_kick,if=level>=34&chi.current>=2&!buff.shuffle.up\n\n# Use Expel Harm if Desperate Measures is active\nactions.core+=/expel_harm,if=buff.desperate_measures.up&chi.current<5*talent.ascension.enabled+4*!talent.ascension.enabled&energy.actual>=40&!talent.power_strikes.enabled\n\n# Use Keg Smash to generate Chi if low and enough energy\nactions.core+=/keg_smash,if=chi.current<3+1*talent.ascension.enabled&energy.actual>=40\n\n# Maintain Tiger Power (level 34+) if missing or expiring\nactions.core+=/tiger_palm,if=level>=34&(buff.tiger_power.down||buff.tiger_power.remains<=2)\n\n# AOE: RJW or Spinning Crane Kick if 3+ targets, high energy, not Chi capped\nactions.core+=/rushing_jade_wind,if=active_enemies>=3&talent.rushing_jade_wind.enabled&cooldown.rushing_jade_wind.ready&energy.actual>=40&chi.current<5*talent.ascension.enabled+4*!talent.ascension.enabled&!talent.power_strikes.enabled\n\n# Use Expel Harm if injured and not Chi capped\nactions.core+=/expel_harm,if=health.percent<100&chi.current<5*talent.ascension.enabled+4*!talent.ascension.enabled&energy.actual>=40&!talent.power_strikes.enabled\n\n# Use Expel Harm if injured and not Chi capped\nactions.core+=/expel_harm,if=health.percent<100&chi.current<3-1*talent.ascension.enabled&energy.actual>=40&!(chi.current>=3&buff.power_strikes.up)\n\n# Refresh Shuffle if it's about to expire or missing\nactions.core+=/blackout_kick,if=level>=34&chi.current>=2&(buff.shuffle.remains<=3||!buff.shuffle.up)\n\n# Use Chi Wave if talented, off cooldown, and not Chi capped\nactions.core+=/chi_wave,if=talent.chi_wave.enabled&cooldown.chi_wave.remains<=0&chi.current<5*talent.ascension.enabled+4*!talent.ascension.enabled&energy.actual<85\n\nactions.core+=/tiger_palm,if=level<34&chi.current>=1&(buff.tiger_power.down||buff.tiger_power.remains<=4)\n\n# Use Breath of Fire if Dizzying Haze is up, target isn't burning, and Shuffle is banked\nactions.core+=/breath_of_fire,if=active_enemies>=3&chi.current>=2&buff.shuffle.remains>11&(debuff.dizzying_haze.up||debuff.dizzying_haze_dot.up)&debuff.breath_of_fire_dot.down\n\n\n# BoK Shuffle\nactions.core+=/blackout_kick,if=chi.current>=2\n\n# Maintain Tiger Power at any level\nactions.core+=/tiger_palm,if=level>=34&(buff.tiger_power.down||buff.tiger_power.remains<=2)\n\n\n# Tiger Palm filler for level 34+ if low energy and nothing else usable\nactions.core+=/tiger_palm,if=level>=34&energy.actual<36&chi.current<=1\n\n# =======================\n# Single Target / Light Cleave (≤2 enemies)\n# =======================\n\n# Jab if fighting ST or light cleave, high energy, and Keg Smash is on cooldown >1.3s\nactions.st+=/jab,if=active_enemies<=2&energy.actual>=87&cooldown.keg_smash.remains>1.3&!talent.power_strikes.enabled\n\n# Jab if fighting ST or light cleave, high energy, and Keg Smash is on cooldown >1.3s with power strikes\nactions.st+=/jab,if=active_enemies<=2&energy.actual>=87&cooldown.keg_smash.remains>1.3&!(chi.current>=3&buff.power_strikes.up)\n\n# Jab for ST or cleave if not Chi capped and energy sufficient\nactions.st+=/jab,if=active_enemies<=2&energy.actual>=40&chi.current<5*talent.ascension.enabled+4*!talent.ascension.enabled&!talent.power_strikes.enabled\n\n# Jab for ST or cleave if not Chi capped and energy sufficient with power strikes\nactions.st+=/jab,if=active_enemies<=2&energy.actual>=40&chi.current<5*talent.ascension.enabled+4*!talent.ascension.enabled&!(chi.current>=3&buff.power_strikes.up)\n\n# =======================\n# AoE (3 or more enemies)\n# =======================\n\n\n# AOE: RJW or Spinning Crane Kick if 3+ targets, high energy, not Chi capped\nactions.aoe+=/rushing_jade_wind,if=active_enemies>=3&talent.rushing_jade_wind.enabled&cooldown.rushing_jade_wind.ready&energy.actual>=60&chi.current<5*talent.ascension.enabled+4*!talent.ascension.enabled&!talent.power_strikes.enabled\n\nactions.aoe+=/spinning_crane_kick,if=active_enemies>=3&!talent.rushing_jade_wind.enabled&energy.actual>=60&chi.current<5*talent.ascension.enabled+4*!talent.ascension.enabled&buff.shuffle.remains>1.9&!talent.power_strikes.enabled\n\n# AOE: RJW or Spinning Crane Kick if 3+ targets, high energy, not Chi capped with power strikes\nactions.aoe+=/spinning_crane_kick,if=active_enemies>=3&!talent.rushing_jade_wind.enabled&energy.actual>=70&chi.current<5*talent.ascension.enabled+4*!talent.ascension.enabled&buff.shuffle.remains>1.9&!(chi.current>=3&buff.power_strikes.up)\n\nactions.aoe+=/rushing_jade_wind,if=active_enemies>=3&talent.rushing_jade_wind.enabled&cooldown.rushing_jade_wind.ready&energy.actual>=40&chi.current<5*talent.ascension.enabled+4*!talent.ascension.enabled&!(chi.current>=3&buff.power_strikes.up)\n\n\n# Spinning Crane Kick fallback\nactions.aoe+=/spinning_crane_kick,if=active_enemies>=3&!talent.rushing_jade_wind.enabled&cooldown.keg_smash.remains>1.9&energy.actual>=40&chi.current<5*talent.ascension.enabled+4*!talent.ascension.enabled\n\n#Spinning Crane Kick with power strikes fallback\nactions.aoe+=/spinning_crane_kick,if=active_enemies>=3&energy.actual>=40&!(chi.current>=3&buff.power_strikes.up)&!talent.rushing_jade_wind.enabled&chi.current<4\n\n\n# Jab fallback when RJW is talentedand is on cooldown and energy is sufficient\nactions.aoe+=/jab,if=active_enemies>=3&talent.rushing_jade_wind.enabled&!cooldown.rushing_jade_wind.ready&energy.actual>=40&(chi.current<5*talent.ascension.enabled+4*!talent.ascension.enabled)&(cooldown.keg_smash.remains)>1.4&!talent.power_strikes.enabled\n\n\n#Jab fallback when RJW is talentedand is on cooldown and energy is sufficient with power strikes\nactions.aoe+=/jab,if=active_enemies>=3&talent.rushing_jade_wind.enabled&!cooldown.rushing_jade_wind.ready&energy.actual>=40&(chi.current<4)&(cooldown.keg_smash.remains)>1.4&!(chi.current>=3&buff.power_strikes.up)\n\n# Jab fallback when lower than 46 and does not know SCK\nactions.aoe+=/jab,if=active_enemies>=3&level<46&!talent.rushing_jade_wind.enabled&cooldown.keg_smash.remains>1.4&energy.actual>=40&chi.current<5*talent.ascension.enabled+4*!talent.ascension.enabled\n\n\n# Tiger Palm filler when Keg Smash is down and nothing else usable\nactions.aoe+=/tiger_palm,if=active_enemies>=3&cooldown.keg_smash.remains>1.4&energy.actual<=40&(level>=34||chi.current>=1)\n\n\n# =======================\n# Main Action List\n# =======================\n\nactions+=/call_action_list,name=defensives\nactions+=/call_action_list,name=tod,if=buff.death_note.up&cooldown.touch_of_death.ready&((!ingroup&target.health.pct>=20)||(ingroup&!ininstance&target.health.pct>=20)||(ingroup&boss))\nactions+=/call_action_list,name=cooldowns\nactions+=/call_action_list,name=overflow,if=(chi.current==5*talent.ascension.enabled+4*!talent.ascension.enabled)\nactions+=/call_action_list,name=core\nactions+=/call_action_list,name=st,if=active_enemies<=2\nactions+=/call_action_list,name=aoe,if=active_enemies>=3\nactions+=auto_attack",
